// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');

// Library: none — native interpolate/spring with SVG masking

const { fontFamily: oswaldFamily } = loadOswald();



export type FocusTargetProps = Record<string, any>;

const FocusTarget: React.FC<FocusTargetProps> = ({
  backgroundColor = "#0C1F43",
  transparentBackground = false,
  durationInSeconds = 5,
  textLine1 = "FOCUS ON THE",
  textLine2 = "20%",
  textColor1 = "#F4F6F6",
  textColor2 = "#6ECF91",
  targetRingColor = "#F4F6F6",
  targetCenterColor = "#6ECF91",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgStyle = transparentBackground ? undefined : backgroundColor;

  // Animation - Text
  const text1Progress = spring({ frame: frame - 5, fps, config: { damping: 14, mass: 0.8 } });
  const text2Progress = spring({ frame: frame - 10, fps, config: { damping: 14, mass: 0.8 } });

  const opacity1 = interpolate(text1Progress, [0, 0.5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const opacity2 = interpolate(text2Progress, [0, 0.5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Animation - Target Rings
  const outerRingScale = spring({ frame: frame - 10, fps, config: { damping: 12, mass: 0.8 } });
  const innerRingScale = spring({ frame: frame - 15, fps, config: { damping: 12, mass: 0.8 } });
  const centerScale = spring({ frame: frame - 20, fps, config: { damping: 12, mass: 0.8 } });

  // Animation - Arrow Flight & Impact
  const arrowEntranceFrame = 25;
  const arrowHitFrame = 32;

  const arrowX = interpolate(frame, [arrowEntranceFrame, arrowHitFrame], [1500, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  // Impact Jolt
  const hitImpact = interpolate(frame, [arrowHitFrame, arrowHitFrame + 4, arrowHitFrame + 18], [0, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const shiftX = hitImpact * -15;
  const shiftY = hitImpact * 10;
  const rotateImpact = hitImpact * -2;

  return (
    <AbsoluteFill style={{ backgroundColor: bgStyle }}>
      {/* Typography Block */}
      <div
        style={{
          position: "absolute",
          left: 150 * s,
          top: 0,
          height: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          maxWidth: 900 * s,
          whiteSpace: "nowrap",
        }}
      >
        <div
          style={{
            fontFamily: oswaldFamily,
            fontSize: 140 * s,
            fontWeight: 700,
            color: textColor1,
            lineHeight: 1,
            textTransform: "uppercase",
            opacity: opacity1,
            transform: `translateY(${interpolate(text1Progress, [0, 1], [40 * s, 0])}px)`,
          }}
        >
          {textLine1}
        </div>
        <div
          style={{
            fontFamily: oswaldFamily,
            fontSize: 480 * s,
            fontWeight: 700,
            color: textColor2,
            lineHeight: 0.85,
            marginTop: -20 * s,
            textTransform: "uppercase",
            opacity: opacity2,
            transform: `translateY(${interpolate(text2Progress, [0, 1], [40 * s, 0])}px)`,
          }}
        >
          {textLine2}
        </div>
      </div>

      {/* Target & Arrow Graphic */}
      <svg
        width={700 * s}
        height={700 * s}
        viewBox="-350 -350 700 700"
        style={{
          position: "absolute",
          right: 150 * s,
          top: "50%",
          transformOrigin: "center",
          transform: `translateY(-50%) translate(${shiftX * s}px, ${shiftY * s}px) rotate(${rotateImpact}deg)`,
          overflow: "visible",
        }}
      >
        <defs>
          <mask id="arrow-cutout-mask">
            {/* The white rect makes everything visible by default */}
            <rect x="-1000" y="-1000" width="2000" height="2000" fill="white" />
            
            {/* The black shapes erase the target, creating the negative space arrow shaft */}
            {frame >= arrowEntranceFrame && (
              <g style={{ transform: `rotate(-35deg)` }}>
                <g style={{ transform: `translateX(${arrowX}px)` }}>
                  <line
                    x1="20"
                    y1="0"
                    x2="300"
                    y2="0"
                    stroke="black"
                    strokeWidth={20}
                    strokeLinecap="round"
                  />
                  <polygon points="0,0 38,-20 28,0 38,20" fill="black" />
                </g>
              </g>
            )}
          </mask>
        </defs>

        {/* Masked Target Geometry */}
        <g mask="url(#arrow-cutout-mask)">
          {outerRingScale > 0 && (
            <circle
              r={220}
              fill="none"
              stroke={targetRingColor}
              strokeWidth={35}
              style={{
                transform: `scale(${outerRingScale})`,
                transformOrigin: "0 0",
              }}
            />
          )}
          {innerRingScale > 0 && (
            <circle
              r={130}
              fill="none"
              stroke={targetRingColor}
              strokeWidth={35}
              style={{
                transform: `scale(${innerRingScale})`,
                transformOrigin: "0 0",
              }}
            />
          )}
          {centerScale > 0 && (
            <circle
              r={60}
              fill={targetCenterColor}
              style={{
                transform: `scale(${centerScale})`,
                transformOrigin: "0 0",
              }}
            />
          )}
        </g>

        {/* Fletchings drawn independently so they remain visible outside the target */}
        {frame >= arrowEntranceFrame && (
          <g style={{ transform: `rotate(-35deg)` }}>
            <g style={{ transform: `translateX(${arrowX}px)` }}>
              <polygon
                points="240,-10 270,-40 300,-40 270,-10"
                fill={textColor2}
              />
              <polygon
                points="240,10 270,40 300,40 270,10"
                fill={textColor2}
              />
            </g>
          </g>
        )}
      </svg>
    </AbsoluteFill>
  );
};

export default FocusTarget;